# Generated by tools/prepare_public_core.py; see CORE_PROVENANCE.json.
from .domain import FACILITY, require
MAX_TELEGRAM_TEXT=3900
PREVIEW_ITEMS=24

def render_original(self, batch_id):
    batch = self.db.connection.execute('SELECT * FROM mvp_notification_batches WHERE batch_id=?', (batch_id,)).fetchone()
    require(batch is not None, 'MVP_BATCH_NOT_FOUND')
    rows = self._item_rows(batch_id)
    scan = self.db.connection.execute('SELECT * FROM monitor_runs WHERE scan_id=?', (batch['scan_id'],)).fetchone()
    observed = self.db.connection.execute('SELECT min(c.observed_at) FROM mvp_notification_batch_items i\n            JOIN notification_opportunities o ON o.opportunity_id=i.opportunity_id\n            JOIN availability_current c ON c.source_id=o.source_id AND c.usage_date=o.usage_date\n             AND c.court=o.court AND c.start_time=o.start_time AND c.end_time=o.end_time\n            WHERE i.batch_id=?', (batch_id,)).fetchone()[0]
    active = sum((row['item_state'] == 'ACTIVE' for row in rows))
    inactive = len(rows) - active
    title = '⚽ Bot DatSan — Tổng hợp sân trống ban đầu' if batch['batch_kind'] == 'INITIAL' else '⚽ Bot DatSan — Cơ hội sân trống mới'
    header = [title, f'Nguồn: Katsushika READ_ONLY · {FACILITY}', f"Đã kiểm tra: {scan['window_start']} → {scan['window_end']}", f'Quan sát: {observed} · JST (snapshot, cần tự kiểm tra lại trước khi đặt)', f'Tổng: {len(rows)} · còn AVAILABLE: {active} · không còn hiệu lực: {inactive}', '']
    item_lines = []
    for row in rows[:PREVIEW_ITEMS]:
        marker = '✓' if row['item_state'] == 'ACTIVE' else '×'
        suffix = '' if marker == '✓' else ' · đã đến giờ sử dụng' if row['item_state'] == 'EXPIRED' else ' · ra khỏi phạm vi, không kết luận RESERVED' if row['invalidation_reason'] == 'OUT_OF_SCOPE' else ' · không còn AVAILABLE'
        item_lines.append(f"{marker} {row['usage_date']} · sân {row['court']} · {row['start_time']}–{row['end_time']}{suffix}")
    hidden = len(rows) - len(item_lines)
    footer = ['', f'Còn {hidden} khung giờ khác. Gõ /available để xem đầy đủ.'] if hidden else ['', 'Gõ /available để xem danh sách hiện tại.']
    changed = [row for row in rows if row['item_state'] != 'ACTIVE'][-3:]
    if changed:
        footer += ['Thay đổi gần đây: ' + '; '.join((f"{r['usage_date']} sân {r['court']} {r['start_time']} ({r['item_state']})" for r in changed))]
    text = '\n'.join(header + item_lines + footer)
    while len(text) > MAX_TELEGRAM_TEXT and item_lines:
        item_lines.pop()
        hidden += 1
        footer = ['', f'Còn {hidden} khung giờ khác. Gõ /available để xem đầy đủ.']
        text = '\n'.join(header + item_lines + footer)
    require(0 < len(text) <= MAX_TELEGRAM_TEXT, 'MVP_BATCH_TEXT_TOO_LONG')
    return text
